local SheepShepherd = {}
local PRODUCTS = {
    wool_sheep = { name = "Volnasta ovca", sheepCost = 1, fodderCost = 1, waterCost = 1, time = 3, cost = 28, yield = 40, happiness = 1, description = "Volnasta ovca za proizvodnjo volne." },
    milk_sheep = { name = "Mlečna ovca", sheepCost = 1, fodderCost = 1, waterCost = 1, time = 4, cost = 38, yield = 50, prestige = 1, description = "Mlečna ovca za ovčje mleko." },
    fat_lamb = { name = "Pitno jagnje", sheepCost = 1, fodderCost = 2, waterCost = 1, time = 5, cost = 65, yield = 60, prestige = 2, happiness = 1, description = "Pitno jagnje za meso." },
    silver_fleece_sheep = { name = "Srebrnoruna ovca", sheepCost = 1, silverCost = 1, fodderCost = 1, waterCost = 1, time = 8, cost = 180, yield = 80, prestige = 7, happiness = 2, description = "Srebrnoruna ovca za plemiče." },
    silver_bell_flock = { name = "Srebrno zvončna čreda", sheepCost = 2, silverCost = 1, fodderCost = 2, waterCost = 1, time = 11, cost = 440, yield = 90, prestige = 13, happiness = 3, description = "Čreda s srebrnimi zvoni za visoke plemiče." },
    royal_grand_flock = { name = "Kraljevski veliki čreda ovc", sheepCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, fodderCost = 4, waterCost = 2, time = 16, cost = 1600, yield = 100, prestige = 36, happiness = 8, description = "Velika kraljevska čreda z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ovčarska postaja", cost = { gold = 220, wood = 120, stone = 200 }, upkeep = 5, qualityBonus = 5 },
    sheep_pasture = { name = "Ovčja paša", cost = { gold = 800, wood = 220, stone = 300, fodder = 10 }, upkeep = 20, qualityBonus = 18 },
    shearing_barn = { name = "Strižnica", cost = { gold = 2000, wood = 350, stone = 600, silver = 25, iron = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_sheep_atelier = { name = "Kraljevski atelje ovc", cost = { gold = 8200, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
SheepShepherd.sheepStock = 22; SheepShepherd.fodderStock = 24; SheepShepherd.waterStock = 18; SheepShepherd.silverStock = 8; SheepShepherd.goldStock = 6; SheepShepherd.jewelStock = 6
SheepShepherd.productStock = {}; SheepShepherd.buildings = {}; SheepShepherd.maker = nil; SheepShepherd.activeMaking = {}; SheepShepherd.totalProducts = 0; SheepShepherd.dayTimer = 0
function SheepShepherd.init() SheepShepherd.sheepStock=22; SheepShepherd.fodderStock=24; SheepShepherd.waterStock=18; SheepShepherd.silverStock=8; SheepShepherd.goldStock=6; SheepShepherd.jewelStock=6; SheepShepherd.productStock={}; SheepShepherd.buildings={}; SheepShepherd.maker=nil; SheepShepherd.activeMaking={}; SheepShepherd.totalProducts=0; SheepShepherd.dayTimer=0; print("[SheepShepherd] Royal Sheep Shepherd System initialized (6 products, 4 buildings)") end
function SheepShepherd.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SheepShepherd.maker={name=n or ("Ovčar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ovčar najet: %s (spretnost: %d)",SheepShepherd.maker.name,s),"success") end; return true end
function SheepShepherd.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SheepShepherd.build(id) local ok,e=SheepShepherd.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SheepShepherd.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SheepShepherd.getQualityBonus() local b=0; for _,bd in ipairs(SheepShepherd.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SheepShepherd.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.sheepCost and SheepShepherd.sheepStock<(d.sheepCost or 0) then return false,"Premalo ovc" end; if d.fodderCost and SheepShepherd.fodderStock<(d.fodderCost or 0) then return false,"Premalo krme" end; if d.waterCost and SheepShepherd.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and SheepShepherd.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SheepShepherd.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SheepShepherd.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SheepShepherd.buildings==0 then return false,"Potrebna delavnica" end; if not SheepShepherd.maker then return false,"Potreben ovčar" end; return true end
function SheepShepherd.make(pt,qty) qty=qty or 5; local ok,e=SheepShepherd.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.sheepCost then SheepShepherd.sheepStock=SheepShepherd.sheepStock-d.sheepCost*qty end; if d.fodderCost then SheepShepherd.fodderStock=SheepShepherd.fodderStock-d.fodderCost*qty end; if d.waterCost then SheepShepherd.waterStock=SheepShepherd.waterStock-d.waterCost*qty end; if d.silverCost then SheepShepherd.silverStock=SheepShepherd.silverStock-d.silverCost*qty end; if d.goldCost then SheepShepherd.goldStock=SheepShepherd.goldStock-d.goldCost*qty end; if d.jewelCost then SheepShepherd.jewelStock=SheepShepherd.jewelStock-d.jewelCost*qty end; local t=d.time; if SheepShepherd.maker then t=math.max(1,t-math.floor(SheepShepherd.maker.skill/12)) end; table.insert(SheepShepherd.activeMaking,{id="sheep_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SheepShepherd.completeMaking(m) local q=1.0+(SheepShepherd.getQualityBonus()/100); if SheepShepherd.maker then q=q+(SheepShepherd.maker.skill/180) end; q=math.min(2.0,q); SheepShepherd.productStock[m.productType]=(SheepShepherd.productStock[m.productType] or 0)+m.quantity; SheepShepherd.totalProducts=SheepShepherd.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SheepShepherd.maker then SheepShepherd.maker.itemsMade=SheepShepherd.maker.itemsMade+m.quantity; if math.random()<0.20 then SheepShepherd.maker.skill=math.min(100,SheepShepherd.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čreda vzrejena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sheep.completed",{productName=m.productName,yield=m.yield,happiness=m.happiness}) end end
function SheepShepherd.update(dt) if not _G.state then return end; SheepShepherd.dayTimer=SheepShepherd.dayTimer+dt; if SheepShepherd.dayTimer>=30 then SheepShepherd.dayTimer=0; for i=#SheepShepherd.activeMaking,1,-1 do local m=SheepShepherd.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SheepShepherd.completeMaking(m); table.remove(SheepShepherd.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SheepShepherd.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SheepShepherd.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SheepShepherd.getStats() return {sheepStock=SheepShepherd.sheepStock,fodderStock=SheepShepherd.fodderStock,waterStock=SheepShepherd.waterStock,silverStock=SheepShepherd.silverStock,goldStock=SheepShepherd.goldStock,jewelStock=SheepShepherd.jewelStock,productStock=SheepShepherd.productStock,numBuildings=#SheepShepherd.buildings,hasMaker=SheepShepherd.maker~=nil,makerName=SheepShepherd.maker and SheepShepherd.maker.name or "—",makerSkill=SheepShepherd.maker and SheepShepherd.maker.skill or 0,activeMaking=#SheepShepherd.activeMaking,totalProducts=SheepShepherd.totalProducts} end
return SheepShepherd
